        "explanation": "Provides concrete next actions and decision triggers.",
        "quote": "是否重新开放引流、是否需要再做CT、是否拔管、是否转普通病房，或突然要签字"
      }
    ],
    "clinical_reasoning_direction": [
      {
        "event_id": "lite_evt_00612",
        "explanation": "Recognizes clinical deterioration and redirects from waiting to urgent bedside escalation.",
        "quote": "已经不能算普通等待了"
      }
    ],
    "continuity_memory_focus": [
      {
        "event_id": "lite_evt_02969",
        "explanation": "Maintains the current phase: ICU, EVD not removed, CT/report uncertainty, and next EVD decisions.",
        "quote": "准备复查CT看下一步，暂时没让再手术，但还没脱险"
      }
    ],
    "medical_safety_risk_recognition": [
      {
        "event_id": "lite_evt_00668",
        "explanation": "Safety-nets neurologic deterioration with immediate in-hospital response.",
        "quote": "立即按铃或直接跑护士站喊医生，不要等线上回复"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_02148",
        "explanation": "Adapts communication into a caregiver-ready family script while preserving uncertainty.",
        "quote": "有一点点好信号，但还没脱险，等明天查房再定"
      }
    ]
  },
  "dimension_ratings": {
    "actionability_responsibility_chain": "excellent",
    "clinical_reasoning_direction": "good",
