    "patient_family_realworld_adaptation": "good"
  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00211",
          "explanation": "Distinguishes completed imaging/raw images from pending formal report and directs appropriate review.",
          "quote": "手机上还没出正式报告"
        },
        {
          "event_id": "lite_evt_01244",
          "explanation": "Separates what is confirmed from what must wait for formal reports and records.",
          "quote": "必须等待的（请务必盯住回传）"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor repeatedly guarded against misreading incomplete or mistimed imaging/status information, such as raw MRI versus formal report and no immediate reoperation versus safety, and integrated this into the plan and family communication.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": false,
      "citations": [],
      "completion": "not_triggered",
      "explanation": "The observable dialogue did not clearly trigger a caregiver belief that a benign tumor meant indefinite waiting, and the doctor did not complete a caregiver-centered correction of that specific misconception.",
      "ho_id": "HO2",
