      "triggered": false
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_01080",
          "explanation": "Clarifies bedside responsibility owner during inpatient deterioration.",
          "quote": "一切由病区的值班医生和护士负责"
        },
        {
          "event_id": "lite_evt_01282",
          "explanation": "Assigns formal report and operative explanation to neurosurgery owner.",
          "quote": "明天查房时，必须当面问主刀或上级医生"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor repaired responsibility-chain gaps by separating ICU/nursing urgent monitoring, neurosurgery or senior surgeon explanations, radiology/CT report issues, anesthesia or operative consent questions, and family notification questions.",
      "ho_id": "HO3",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
